import "node:module";
const WORKER_CLEANUP_REGISTRY = Symbol.for('rstest.worker.cleanup.registry');
const getWorkerCleanupRegistry = ()=>{
    const globalObject = globalThis;
    let registry = globalObject[WORKER_CLEANUP_REGISTRY];
    if (!registry) {
        registry = new Set();
        globalObject[WORKER_CLEANUP_REGISTRY] = registry;
    }
    return registry;
};
const registerWorkerCleanup = (cleanup)=>{
    const registry = getWorkerCleanupRegistry();
    registry.add(cleanup);
    return ()=>registry.delete(cleanup);
};
const takeWorkerCleanups = ()=>{
    const registry = getWorkerCleanupRegistry();
    const cleanups = [
        ...registry
    ];
    registry.clear();
    return cleanups;
};
export { registerWorkerCleanup, takeWorkerCleanups };
